/// <summary>
/// Bug 306156: [MS] CB201 - Customer rebates: Attribute Filtering Logic Not Correct - MS SR # 2410100030001214
/// MS code
/// </summary>
[ExtensionOf(classStr(GUPHashHelper))]
final class METGUPHashHelper_Extension
{
}

Method.Source:
/// <summary>
/// MS code
/// When the rule is using OR conditions, we should skip the original logic to check table/line attributes which are seperated from product/customer attributes because OR condition rules has been handled in query builder(AMRebateQueryBuilder_GlobalUnifiedPricing_Extension).
/// </summary>
/// <param name = "_ruleId">RuleId</param>
/// <returns>boolean</returns>
public static boolean skipCheckRuleMatchedWithTableOrLineAttribute(RecId _ruleId)
{
    boolean ret = next skipCheckRuleMatchedWithTableOrLineAttribute(_ruleId);

    if (!ret
    &&  TAMRebateParameters::find().METUseOrAttributes)
    {
        GUPPricingRuleCondition ruleCondition;
        select firstonly RecId from ruleCondition
            where ruleCondition.RuleId == _ruleId
               && ruleCondition.METisOR == NoYes::Yes;

        if (ruleCondition.RecId)
        {
            return true;
        }
    }

    return ret;
}

/// <summary>
/// MS code
/// When updating all hashes, we should also to clear OR rule structure table.
/// </summary>
public static void updateHashAll()
{
    if (TAMRebateParameters::find().METUseOrAttributes)
    {
        METGUPPricingAttributeGroupRef groupRef;
        delete_from groupRef;

        METGUPPricingAttributeLinkRelation linkRelation;
        delete_from linkRelation;
    }

    next updateHashAll();
}

/// <summary>
/// MS code
/// When insert rule hash, the structure of OR condition rules should also be inserted.
/// </summary>
/// <param name = "_pricingRule">GUPPricingRule</param>
/// <param name = "_recordInsertList">RecordInsertList</param>

public static void insertRuleHash(GUPPricingRule _pricingRule, RecordInsertList _recordInsertList)
{
    next insertRuleHash(_pricingRule, _recordInsertList);

    if (TAMRebateParameters::find().METUseOrAttributes)
    {
        GUPRuleHash::insertStruct(_pricingRule);
    }
}

/// <summary>
/// MS code
/// Generate hash for transaction
/// </summary>
/// <param name = "_attributeGroupName">GUPPricingAttributeGroupName</param>
/// <param name = "_pricingObject">Common</param>
/// <param name = "_productAttributeValues">Map</param>
/// <param name = "_salesLineAttributeValues">Map</param>
/// <param name = "_customerAttributeValues">Map</param>
/// <param name = "_salesTableAttributeValues">Map</param>
/// <param name = "_custTable">CustTable</param>
/// <param name = "_isSalesQuotation">boolean</param>
/// <param name = "_isPriceSimulator">boolean</param>
/// <param name = "_isPriceReport">boolean</param>
/// <param name = "_salesTransactionId">anytype</param>
/// <param name = "_salesLineNum">anytype</param>
/// <returns>Set</returns>
public static Set getHashKeySetOneGroup(
    GUPPricingAttributeGroupName _attributeGroupName,
    Common _pricingObject,
    Map _productAttributeValues,
    Map _salesLineAttributeValues,
    Map _customerAttributeValues,
    Map _salesTableAttributeValues,
    CustTable _custTable,
    boolean _isSalesQuotation,
    boolean _isPriceSimulator,
    boolean _isPriceReport,
    anytype _salesTransactionId,
    anytype _salesLineNum)
{
    // The orignal logic to generate hash for normal rule which is not considering OR relation
    Set hashKeySetOneGroup = next getHashKeySetOneGroup(
        _attributeGroupName,
        _pricingObject,
        _productAttributeValues,
        _salesLineAttributeValues,
        _customerAttributeValues,
        _salesTableAttributeValues,
        _custTable,
        _isSalesQuotation,
        _isPriceSimulator,
        _isPriceReport,
        _salesTransactionId,
        _salesLineNum);

    if (TAMRebateParameters::find().METUseOrAttributes)
    {
        METGUPPricingAttributeGroupRef groupRef;
        while select RecId from groupRef
            where groupRef.PriceAttributeGroupName == _attributeGroupName
        {

            /*
For example, one structure is like this:
Attributes: A1, A2, A3, A4, A5

        A1    OR
        A2    OR
        A3    OR
        A4
        A5

Values:     V1, V2, V3, V4, V5
transction properties:
        A1:V1
        A2:V2
        A3:V3
        A4:V4
        A5:V5
            */
            Set hashKeySetOneGroupWithOrCondition = new Set(Types::String);
            METGUPPricingAttributeLinkRelation linkRelation;
            GUPPricingAttributeLink attributeLink;

            // AND Attributes first
            while select AttributeName, TypeName, RecId, PriceAttributeClassId, Source, AttributeProviderClassId from attributeLink
                order by attributeLink.Priority
                join RecId from linkRelation
                where linkRelation.PriceAttributeGroupName == _attributeGroupName
                   && linkRelation.AttrGroupRefRecId == groupRef.RecId
                   && linkRelation.AttrLinkRecId == attributeLink.RecId
                   && linkRelation.isOR == NoYes::No
            {
                List propertyValueList = GUPHashHelper::getPropertyValueListForHash(
                    _pricingObject,
                    attributeLink,
                    _customerAttributeValues,
                    _salesTableAttributeValues,
                    _productAttributeValues,
                    _salesLineAttributeValues,
                    _custTable,
                    _isSalesQuotation,
                    _isPriceSimulator,
                    _isPriceReport,
                    _salesTransactionId,
                    _salesLineNum);

                hashKeySetOneGroupWithOrCondition = GUPHashHelper::refreshHashKeySetOneGroup(hashKeySetOneGroupWithOrCondition, propertyValueList, attributeLink);
            }
            /*
=>  HASH STRING FOR AND ATTRIBUTES
      [A4:V4/A5:V5,
       A4:V4/A5:ALL,
       A4:ALL/A5:V5,
       A4:ALL/A5:ALL]
            */

            // Then OR attributes
            Set orConditionValueSet = new Set(Types::String);
            str currentValue;
            while select AttributeName, TypeName, RecId, PriceAttributeClassId, Source, AttributeProviderClassId from attributeLink
                order by attributeLink.Priority
                join RecId from linkRelation
                where linkRelation.PriceAttributeGroupName == _attributeGroupName
                   && linkRelation.AttrGroupRefRecId == groupRef.RecId
                   && linkRelation.AttrLinkRecId == attributeLink.RecId
                   && linkRelation.isOR == NoYes::Yes
            {
                List propertyValueList = GUPHashHelper::getPropertyValueListForHash(
                    _pricingObject,
                    attributeLink,
                    _customerAttributeValues,
                    _salesTableAttributeValues,
                    _productAttributeValues,
                    _salesLineAttributeValues,
                    _custTable,
                    _isSalesQuotation,
                    _isPriceSimulator,
                    _isPriceReport,
                    _salesTransactionId,
                    _salesLineNum);

                ListEnumerator propertyValueEnum = propertyValueList.getEnumerator();
                while (propertyValueEnum.moveNext())
                {
                    currentValue = strLRTrim(strLwr(propertyValueEnum.current()));
                    orConditionValueSet.add(currentValue == GUPHashHelper::getAllValue() ? GUPHashHelper::getAllValue() : int642Str(attributeLink.RecId) + GUPHashHelper::getColonChar() + currentValue);
                }
            }

            /*
=>  HASH STRING FOR OR ATTRIBUTE
      [A1:V1,
       A2:V2,
       A3:V3,
       ALL]
            */

            // concat the AND attributes and OR attributes
            if (!orConditionValueSet.empty())
            {
                if (hashKeySetOneGroupWithOrCondition.empty())
                {
                    hashKeySetOneGroupWithOrCondition = orConditionValueSet;
                }
                else
                {
                    Set newHashKeys = new Set(Types::String);
                    SetEnumerator setEnumerator = hashKeySetOneGroupWithOrCondition.getEnumerator();
                    while (setEnumerator.moveNext())
                    {
                        SetEnumerator propertyValueEnum = orConditionValueSet.getEnumerator();
                        while (propertyValueEnum.moveNext())
                        {
                            newHashKeys.add(setEnumerator.current() + GUPHashHelper::getSlashChar() + propertyValueEnum.current());
                        }
                    }
                    hashKeySetOneGroupWithOrCondition = newHashKeys;
                }
            }

            if (!hashKeySetOneGroupWithOrCondition.empty())
            {
                hashKeySetOneGroup = Set::union(hashKeySetOneGroup, hashKeySetOneGroupWithOrCondition);
            }

            /*
=>  HASH STRING AT THE END
      [A4:V4/A5:V5/A1:V1,
       A4:V4/A5:V5/A2:V2,
       A4:V4/A5:V5/A3:V3,
       A4:V4/A5:V5/ALL,
       A4:V4/A5:ALL/A1:V1,
       A4:V4/A5:ALL/A2:V2,
       A4:V4/A5:ALL/A3:V3,
       A4:V4/A5:ALL/ALL,
       A4:ALL/A5:V5/A1:V1,
       A4:ALL/A5:V5/A2:V2,
       A4:ALL/A5:V5/A3:V3,
       A4:ALL/A5:V5/ALL,
       A4:ALL/A5:ALL/A1:V1,
       A4:ALL/A5:ALL/A2:V2,
       A4:ALL/A5:ALL/A3:V3,
       A4:ALL/A5:ALL/ALL]
            */
        }
    }

    return hashKeySetOneGroup;
}
